var ols=[{caption:"DEPARTMENT OF FORENSIC SCIENCE",page:"1",url:"",level:"1",children:[{caption:"ISSN: 2583-7044 (Online) Title: Veritas",page:"1",url:"",level:"2",children:[]}]},{caption:"Vol.5, Issue 2",page:"1",url:"",level:"1",children:[]},{caption:"MESSAGE FROM THE VICE CHANCELLOR",page:"2",url:"",level:"1",children:[{caption:"Rev. Fr. Dr.Augustine George Vice Chancellor",page:"2",url:"",level:"2",children:[]}]},{caption:"MESSAGE FROM THE DEAN",page:"3",url:"",level:"1",children:[{caption:"Dr Vijayanand S Dean School of Biological and Forensic Sciences",page:"3",url:"",level:"2",children:[]}]},{caption:"ADVISORY BOARD",page:"4",url:"",level:"1",children:[]},{caption:"EDITORIAL BOARD",page:"4",url:"",level:"1",children:[{caption:"FACULTY",page:"4",url:"",level:"2",children:[]}]},{caption:"EDITORIAL  BOARD STUDENTS",page:"5",url:"",level:"1",children:[{caption:"ELINA ANN JIBU",page:"5",url:"",level:"2",children:[]},{caption:"TEJASWINI T S",page:"5",url:"",level:"2",children:[]},{caption:"SWATI SHANOJ  T",page:"5",url:"",level:"2",children:[]},{caption:"SNEHA BEJOY",page:"5",url:"",level:"2",children:[]},{caption:"REVIEW TEAM",page:"5",url:"",level:"2",children:[{caption:"PRIYANKA  GHOSH",page:"5",url:"",level:"3",children:[]},{caption:"ERICK JOSE",page:"5",url:"",level:"3",children:[]},{caption:"JIYA PATEL",page:"5",url:"",level:"3",children:[]},{caption:"YUKTHA  SHREE T S",page:"5",url:"",level:"3",children:[]},{caption:"SREEVIDYA           REJITH",page:"5",url:"",level:"3",children:[]}]}]},{caption:"EDITING TEAM",page:"5",url:"",level:"1",children:[]},{caption:"EDITORIAL  BOARD STUDENTS",page:"6",url:"",level:"1",children:[{caption:"ANANYA SINGH",page:"6",url:"",level:"2",children:[{caption:"VI Sem BSc. Forensic Science, Biotechnology",page:"6",url:"",level:"3",children:[]}]},{caption:"VISHNU A.",page:"6",url:"",level:"2",children:[{caption:"IV Sem BSc. Forensic Science",page:"6",url:"",level:"3",children:[]}]},{caption:"CREATIVE TEAM",page:"6",url:"",level:"2",children:[{caption:"NAKISHISHA  MARBANIANG",page:"6",url:"",level:"3",children:[{caption:"VI Sem BSc. Forensic  Science",page:"6",url:"",level:"4",children:[]}]},{caption:"DHANUSH  PADAMATI",page:"6",url:"",level:"3",children:[{caption:"IV Sem BSc. Forensic  Science",page:"6",url:"",level:"4",children:[]}]},{caption:"DEBOLEENA  GUHA",page:"6",url:"",level:"3",children:[{caption:"VI Sem BSc. Forensic  Science",page:"6",url:"",level:"4",children:[]},{caption:"ABHINANDAN NAGABHUSHANA",page:"6",url:"",level:"4",children:[]}]}]}]},{caption:"DESIGNING TEAM",page:"6",url:"",level:"1",children:[]},{caption:"TABLE OF CONTENTS",page:"7",url:"",level:"1",children:[]},{caption:"DEPARTMENT",page:"8",url:"",level:"1",children:[]},{caption:"ACTIVITIES",page:"8",url:"",level:"1",children:[{caption:"Date: 17/02/2026",page:"9",url:"",level:"2",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"9",url:"",level:"2",children:[]}]},{caption:"INQUISITOR 2026",page:"9",url:"",level:"1",children:[{caption:"NATIONAL INTERCOLLEGIATE FORENSIC SCIENCE FEST",page:"9",url:"",level:"2",children:[{caption:"Name and details of the Chief Guest: Mr. Manohar Bangera, Chief Marketing Officer at Vedicon Solutions Pvt. Ltd., Bengaluru No of beneficiaries: 122",page:"9",url:"",level:"3",children:[]},{caption:"Objective:  To stimulate and promote students to improve their understanding of their core skills and channel their participation to extra-curricular and co-curricular events.",page:"9",url:"",level:"3",children:[]},{caption:"Write up on the Programme: The Forensic Science Club, under the Department of Forensic Science at Kristu Jayanti University, hosted INQUISITOR 2026, the 5th edition of the National Intercollegiate Forensic Science Fest, on 17th February 2026.",page:"9",url:"",level:"3",children:[]},{caption:"Designed exclusively for students from institutions across the country, the fest aimed to assess and enhance participants’ investigative aptitude, analytical reasoning, courtroom skills, and overall understanding of forensic science through a diverse range of intellectually stimulating events. Organized under the guidance of the Faculty Coordinators, Ms. Aathmika S. and Ms. Pallavi A. Rao, the fest was driven by the dedicated efforts of the Forensic Science Club. The club secretaries, Mr. Sam Daniel and Ms. Aishini G., played a",page:"9",url:"",level:"3",children:[]},{caption:"pivotal role in energizing and coordinating the event, while Event Coordinators Mr. Mishael Godwin and Ms. Sri Ineya ensured meticulous planning and seamless execution. The collective teamwork and commitment of the student organizers transformed the vision of INQUISITOR 2026 into a grand success. The fest witnessed the enthusiastic participation of over 100 students representing more than 11 institutions nationwide, reflecting the growing academic interest in forensic science and allied disciplines. Students from Forensic Science,",page:"9",url:"",level:"3",children:[]}]},{caption:"Life Sciences, Law, and related fields competed in a spirit of healthy competition and collaboration. To maintain fairness and exclusivity, the fest was open only to external participants, ensuring an unbiased competitive platform. Each event was structured with clear guidelines and evaluation criteria to uphold transparency and academic integrity. The inaugural ceremony was graced by Chief Guest Mr. Manohar Bangera, Chief Marketing Officer at Vedicon Solutions Pvt Ltd., whose professional insights and motivational address inspired the participants. As part of the Jayantian tradition, Rev. Fr. Dr. Lijo P. Thomas, Pro Vice Chancellor and Director, School of Law, honoured the Chief Guest with a plant sapling symbolizing growth and knowledge. His presence and words of encouragement added great value to the occasion. INQUISITOR 2026 stood as a celebration of inquiry, innovation, and intellectual empowerment. The fest once again reaffirmed its position as a premier national platform dedicated to nurturing the forensic minds of tomorrow.",page:"10",url:"",level:"2",children:[]}]},{caption:"Events Conducted for Inter Collegiate Fest:",page:"10",url:"",level:"1",children:[{caption:"1. Objection Overruled – A mock trial event testing forensic reasoning, argumentative skills, and courtroom strategy across two competitive rounds. 2. Sherlock & Watson – A personality-based forensic contest where participants processed a crime scene, analyzed evidence, and delivered expert witness testimony. 3. Cross Examination – A case study presentation event evaluating analytical depth and forensic reasoning. 4. Wiz Quiz – A two-round forensic science quiz challenging participants’ subject knowledge and speed. 5. Life Jacket – A role-play event navigating participants through a forensic-themed investigative scenario. 6. CrimeToonist – A creative sketching competition assessing observation and forensic illustration skills. 7. Room of Opinions – A debate event evaluating persuasive abilities and critical forensic reasoning. 8. Tail a Trail – A crime-scene-based challenge testing observation, deduction, and problem-solving skills. 9. Foren X – A business proposal competition encouraging entrepreneurial thinking and innovative solutions to contemporary forensic challenges. 10. CSI’s Canvas – A detailed sketching event focusing on precision, attention to detail, and accurate visual portrayal.",page:"10",url:"",level:"2",children:[]}]},{caption:"ICAFS 2026",page:"11",url:"",level:"1",children:[{caption:"INTERNATIONAL CONFERENCE ON ADVANCES IN FORENSIC SCIENCE",page:"11",url:"",level:"2",children:[{caption:"List of Resource Persons with details",page:"11",url:"",level:"3",children:[]},{caption:"Session details",page:"11",url:"",level:"3",children:[]},{caption:"Name",page:"11",url:"",level:"3",children:[]},{caption:"Designation",page:"11",url:"",level:"3",children:[]},{caption:"Organisation",page:"11",url:"",level:"3",children:[]},{caption:"Objectives:",page:"11",url:"",level:"3",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"12",url:"",level:"3",children:[]},{caption:"Date: 12/03/2026 - 13/03/2026",page:"12",url:"",level:"3",children:[]}]}]},{caption:"Session I: Integration of Law & Forensic Technology in the Age of AI and Data Protection",page:"12",url:"",level:"1",children:[{caption:"RESOURCE PERSON: DR. G.K. GOSWAMI",page:"12",url:"",level:"2",children:[{caption:"Write-up: Dr. G.K. Goswami delivered a thought-provoking session on the evolving intersection of law and forensic technology in the era of artificial intelligence and data protection. He emphasized how rapid advancements in AI-driven tools have transformed forensic investigations, enabling more efficient analysis of digital evidence, pattern recognition, and predictive capabilities. Dr. Goswami discussed the growing reliance on technologies such as digital forensics, biometric systems, and data analytics in criminal justice, while also cautioning about the legal and ethical challenges they pose. He highlighted concerns related to data privacy, consent, surveillance, and the potential misuse of sensitive information, stressing the importance of robust data protection frameworks. The session also addressed the need for laws to keep pace with technological developments, ensuring accountability, transparency, and admissibility of AI-generated evidence in courts. Dr. Goswami underscored the",page:"12",url:"",level:"3",children:[]},{caption:"significance of maintaining the integrity and reliability of forensic processes in an increasingly digital landscape. He concluded by advocating for a balanced approach that integrates technological innovation with strong legal safeguards, along with interdisciplinary collaboration between legal experts, forensic scientists, and technologists to uphold justice in the modern age.",page:"12",url:"",level:"3",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"13",url:"",level:"3",children:[]},{caption:"Date: 12/03/2026 - 13/03/2026",page:"13",url:"",level:"3",children:[]}]}]},{caption:"Session II: Significance of Skill-Based Training in Forensic Science under NEP-2020",page:"13",url:"",level:"1",children:[{caption:"RESOURCE PERSON: DR. G. S. SODHI",page:"13",url:"",level:"2",children:[{caption:"Write-up: Dr. G. S. Sodhi delivered an insightful session highlighting the importance of skill-based training in forensic science in alignment with the National Education Policy (NEP) 2020. He emphasized the shift from traditional theoretical learning to a more practical, hands-on approach that equips students with industry-relevant competencies. Dr. Sodhi discussed how integrating laboratory skills, field training, and interdisciplinary exposure enhances the employability and professional readiness of forensic graduates. He also elaborated on the need for curriculum reforms, collaboration with forensic laboratories, and the incorporation of emerging technologies in academic programs. The session underscored the role of educators in fostering critical thinking, analytical abilities, and ethical practices among students. He concluded by stressing that skill-oriented education is essential for strengthening the forensic science ecosystem and meeting the evolving demands of the criminal justice system.",page:"13",url:"",level:"3",children:[]},{caption:"Date: 12/03/2026 - 13/03/2026",page:"14",url:"",level:"3",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"14",url:"",level:"3",children:[]}]}]},{caption:"Session III: NAFIS – The Game Changer",page:"14",url:"",level:"1",children:[{caption:"RESOURCE PERSON: DR. S. INDIRA SUDHA",page:"14",url:"",level:"2",children:[{caption:"Write-up: Dr. S. Indira Sudha delivered a highly informative session on the National Automated Fingerprint Identification System (NAFIS) and its transformative impact on criminal investigations. She explained how NAFIS has revolutionized fingerprint analysis by enabling centralized, real-time access to fingerprint data across the country. Dr. Sudha highlighted the system’s role in improving the speed and accuracy of criminal identification, aiding law enforcement agencies in solving cases more efficiently. She also discussed the technical aspects of fingerprint digitization, database integration, and matching algorithms, along with challenges such as data standardization and system implementation. The session emphasized the importance of maintaining data integrity, security, and proper training of personnel. Dr. Sudha concluded by stating that NAFIS represents a significant advancement in forensic identification and a major step toward modernizing policing in India.",page:"14",url:"",level:"3",children:[]},{caption:"Date: 12/03/2026 - 13/03/2026",page:"15",url:"",level:"3",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"15",url:"",level:"3",children:[]}]}]},{caption:"Session IV: Reshaping Modern Forensic Biology: Analytical Advancements and Emerging Trends",page:"15",url:"",level:"1",children:[{caption:"RESOURCE PERSON: DR. APARNA R",page:"15",url:"",level:"2",children:[{caption:"Write-up: Dr. Aparna R delivered an engaging session on the recent advancements and emerging trends in forensic biology. She highlighted the evolution of analytical techniques, including advanced DNA profiling methods, next-generation sequencing, and bioinformatics tools, which have significantly enhanced the accuracy and sensitivity of biological evidence analysis. Dr. Aparna discussed how these innovations are reshaping forensic investigations by enabling the analysis of degraded samples, complex mixtures, and trace evidence. She also addressed the challenges associated with interpretation, validation, and ethical considerations in the use of advanced technologies. The session emphasized the importance of continuous research, standardization of protocols, and integration of new methodologies into forensic practice. She concluded by underscoring the need for skilled professionals to effectively utilize these advancements in solving complex criminal cases.",page:"15",url:"",level:"3",children:[]},{caption:"Date: 12/03/2026 - 13/03/2026",page:"16",url:"",level:"3",children:[]},{caption:"Time: 9:30 A.M to 4:30 P.M",page:"16",url:"",level:"3",children:[]}]}]},{caption:"Poster Presentation Session",page:"16",url:"",level:"1",children:[{caption:"Panel Members:",page:"16",url:"",level:"2",children:[{caption:"Dr. Manashree Mane, Assistant Professor, Jain Deemed to be University, Bengaluru, Karnataka",page:"16",url:"",level:"3",children:[]},{caption:"Dr. Aparna R, Assistant Professor, Jain Deemed to be University, Bengaluru, Karnataka",page:"16",url:"",level:"3",children:[]},{caption:"Write-up: The conference also featured an engaging scientific presentation session comprising a total of 87 research papers, including 43 oral presentations and 44 poster presentations. These contributions covered a diverse range of contemporary topics, innovative methodologies, and emerging advancements in the field of forensic and allied sciences. Participants presented their work with clarity, scientific rigour, and creativity, fostering a vibrant and intellectually stimulating academic environment. The poster presentations were evaluated by the esteemed panel members, Dr. Manashree Mane and Dr. Aparna R, who assessed each entry based on scientific relevance, originality, presentation quality, and overall contribution to the discipline. Their expert evaluation and constructive feedback greatly enriched the experience for the participants. At the conclusion of the",page:"16",url:"",level:"3",children:[]},{caption:"session, three outstanding posters were selected for awards in recognition of their excellence and impact. The session provided an excellent platform for researchers to engage in scholarly exchange, gain valuable insights, and showcase their contributions to the scientific community, thereby contributing to the overall success of the conference.",page:"16",url:"",level:"3",children:[]}]}]},{caption:"Outcomes:",page:"17",url:"",level:"1",children:[]},{caption:"IN COLLABORATION WITH PERKINELMER, PVT LTD.",page:"18",url:"",level:"1",children:[]},{caption:"Outcomes:",page:"19",url:"",level:"1",children:[]},{caption:"CUTTING-EDGE FORENSIC RESEARCH IN MEDICOLEGAL INVESTIGATIONS",page:"20",url:"",level:"1",children:[]},{caption:"is always an estimate. The lecture addressed the humanitarian applications of forensic taphonomy in mass disasters, mass burials, and public health emergencies, emphasizing victim identification and dignified handling of remains. Key discussions included osteological examination, forensic anthropology techniques for sex estimation, and classical methods such as Purkait’s triangle. Advanced research approaches, including proteomics and DNA analysis, were explained, particularly their relevance in cases with poor DNA preservation.",page:"21",url:"",level:"1",children:[]},{caption:"Dr. Nasir also introduced the Forensic Anthropology Center for Taphonomy (FACT) at Yenepoya University, established in 2024, highlighting its research infrastructure and international collaborations. The session concluded with a hands-on practical exercise on sex estimation of a skull using Walker’s System (2008), enabling participants to apply theoretical knowledge to practical analysis. Overall, the lecture emphasized scientific objectivity, interdisciplinary research, and continuous learning as essential components of effective forensic practice.",page:"21",url:"",level:"1",children:[]},{caption:"HOW MONEY CRIMES AFFECT YOU MORE THAN YOU THINK",page:"22",url:"",level:"1",children:[]},{caption:"MOBILE FORENSICS: THE NEW AGE INVESTIGATION TOOL",page:"23",url:"",level:"1",children:[]},{caption:"Outcome:",page:"24",url:"",level:"1",children:[]},{caption:"YOUNG VOICES FOR HUMAN RIGHTS AND SOCIAL JUSTICE",page:"25",url:"",level:"1",children:[]},{caption:"Impact Analysis",page:"26",url:"",level:"1",children:[]},{caption:"increased engagement during discussions, with beneficiaries sharing personal experiences and reflecting on their behaviour. Some individuals reported adopting small but meaningful changes such as showing respect to others, helping neighbours, and being more mindful of their actions. From the students’ perspective, there was a significant improvement in communication skills, confidence, and social awareness. The activity encouraged them to think beyond academics and understand real-world social issues. Overall, the programme created a measurable impact by enhancing value-based awareness, promoting positive behavioural intentions, and strengthening the connection between students and the community.",page:"27",url:"",level:"1",children:[]},{caption:"EDUCATING COMMUNITIES ON SUSTAINABLE WATER USE",page:"28",url:"",level:"1",children:[{caption:"Report on the Visit:                                                 The B.Sc. FSBTBC 2nd semester students organized an extension activity on “Awareness on Sustainable Use of Water” on 18th March 2026, intending to educate the community about water conservation, efficient usage, and the importance of preserving this vital resource for future generations. A total of 70 students actively participated in the programme, reaching 11 beneficiaries across Kothanur, K. Narayanapura, and nearby areas around the university. The activity involved interactive sessions, small group discussions, and awareness campaigns conducted at household and neighbourhood levels. Students explained practical methods of water conservation, such as reducing wastage, rainwater harvesting, the reuse of water, and mindful daily consumption. Informative communication was tailored to suit different groups, ensuring clarity and better understanding among beneficiaries. The intended impact of this programme was to encourage responsible water usage and promote sustainable habits within the community. Students benefited by enhancing their communication skills, teamwork, and environmental awareness. The community gained insight into simple yet effective water-saving practices, contributing to long-term sustainability in the neighbourhood. The relevance of domain knowledge was evident as students applied their academic understanding of environmental science and sustainability to real-life situations, thereby",page:"29",url:"",level:"2",children:[]},{caption:"bridging theoretical knowledge with practical community engagement.",page:"29",url:"",level:"2",children:[]}]},{caption:"Impact Analysis",page:"29",url:"",level:"1",children:[{caption:"Before the activity, the beneficiaries had only a basic awareness of water conservation and often practised unregulated water usage in daily activities. Methods such as rainwater harvesting, reuse of greywater, and controlled consumption were either not widely known or not regularly implemented. There was limited understanding of the long-term consequences of water wastage on the environment and community. After the awareness programme conducted on 18th March 2026, positive changes were observed among the 11 beneficiaries. Participants showed improved knowledge of sustainable water practices and expressed willingness to adopt simple conservation methods in their daily lives. Some beneficiaries acknowledged the importance of reducing water wastage, fixing leaks, and reusing water for household purposes such as gardening and cleaning. Increased engagement during the sessions reflected a better understanding of the topic.",page:"29",url:"",level:"2",children:[]}]},{caption:"From the students’ perspective, the activity enhanced their practical knowledge, communication skills, and environmental responsibility. They developed a deeper appreciation of sustainability issues and their role in community education. Overall, the programme resulted in increased awareness, positive behavioural intentions toward water conservation, and strengthened the link between academic learning and real-world environmental responsibility within the community.",page:"30",url:"",level:"1",children:[]},{caption:"CASE",page:"31",url:"",level:"1",children:[]},{caption:"STUDIES",page:"31",url:"",level:"1",children:[]},{caption:"MURDER OF PRADYUMAN THAKUR",page:"32",url:"",level:"1",children:[{caption:"Medha Manoj Nair",page:"32",url:"",level:"2",children:[]},{caption:"Introduction",page:"32",url:"",level:"2",children:[{caption:"Pradyuman Thakur, a 7-year-old boy, was found with his throat slit outside the bathroom of the school he studied in on 8 September 2017 and later succumbed to his injuries. The investigation began with charges against a bus conductor and continues with the trial of a 16-year-old student from the same school. The case attracted nationwide attention and became widely discussed.",page:"32",url:"",level:"3",children:[]}]},{caption:"The Actus Reas (The Guilty Act)",page:"32",url:"",level:"2",children:[{caption:"At 7:55 am, Barun Thakur drops his 7-year-old son Pradyuman and 11-year-old daughter Vidhi at Ryan International School in Gurugram, Haryana. He later stated that he preferred dropping them himself rather than using the school bus due to safety concerns. At 8:08 am, students alerted school staff about Pradyuman’s condition,and he was found bleeding from two neck injuries outside a bathroom near his classroom on the ground floor. He was lifted with the help of bus conductor Ashok Kumar and taken to a nearby hospital in Badshahpur and later transferred to Artemis Hospital in Gurugram, where he was declared dead on arrival. His parents reached the hospital after being informed at 8:15 am.",page:"32",url:"",level:"3",children:[]}]},{caption:"The Haryana Police Investigation",page:"33",url:"",level:"2",children:[{caption:"During the initial investigation conducted at 11:30 am on the same day, the police recovered a bloodied knife from the scene and identified fingerprints. A witness video showed school authorities asking Ashok Kumar to assist in transporting the child, explaining the blood on his shirt. At 12 noon, the police arrested Kumar as the prime suspect. The Deputy Commissioner of Police, Sumit Kumar, stated that the conductor had gone into the washroom after arriving with the bus, taken a knife from the bus toolkit, and encountered Pradyuman. He allegedly attempted sexual assault and attacked the child when he resisted. This arrest was not satisfactory to the public or the victim’s family, who believed Kumar was being framed. Statements from school staff indicated that he was pressured into",page:"33",url:"",level:"3",children:[]},{caption:"confessing and that his shirt was not bloodied before he helped carry the child. A medical examination ruled out any signs of sexual assault. Kumar maintained his innocence and alleged police torture. On 28 February 2018, he was acquitted of all charges by a special court.",page:"33",url:"",level:"3",children:[]}]}]},{caption:"DID YOU KNOW",page:"33",url:"",level:"1",children:[{caption:"Following the Pradyuman Thakur case, mandatory police verification and background checks for all school staff were implemented nationwide.",page:"33",url:"",level:"2",children:[]}]},{caption:"The CBI Investigation",page:"34",url:"",level:"1",children:[{caption:"The investigation was reopened by the CBI, which recovered a different knife identified as the murder weapon from a washroom. CCTV footage showed other students near the crime scene. On re-examination, forensic evidence did not match Ashok Kumar. Bloodstains on Pradyuman’s shirt did not belong to him and were unmatched to Kumar. On 7 November 2017, a Class XI student of the same school was arrested. He had initially reported the incident, but CCTV showed him exiting the washroom at the time of the crime. The CBI stated that the suspect was identified through forensic evidence and cell records.",page:"34",url:"",level:"2",children:[]},{caption:"The Juvenile Justice Board permitted interrogation, during which he confessed in the presence of his father, an independent witness, and a juvenile welfare officer. After evaluating his mental and physical condition, the board ruled that he would be tried as an adult.",page:"34",url:"",level:"2",children:[]}]},{caption:"The Mens Rea (The Guilty Mind)",page:"34",url:"",level:"1",children:[{caption:"According to the CBI, the accused committed the crime to avoid academic pressure. He had an examination scheduled on the same day, along with upcoming tests and a parent-teacher meeting. Investigators stated that he believed a shocking act would disrupt school functioning and lead to cancellation of these obligations. Although the act initially appeared random, it was later concluded that the accused and Pradyuman knew each other through a common music class.",page:"34",url:"",level:"2",children:[]}]},{caption:"Conclusion",page:"34",url:"",level:"1",children:[{caption:"The trial in this case continues, with no final verdict delivered. The accused, now a 21-year-old, remains under legal proceedings. The case is sub judice and has led to significant debate on juvenile justice laws, school safety, and the importance of proper forensic investigation.",page:"34",url:"",level:"2",children:[]}]},{caption:"References",page:"34",url:"",level:"1",children:[{caption:"Murder of Pradyuman Thakur https://en.wikipedia.org/wiki/Murder_of_Pradyuman_Thakur#cite_note-:7-6",page:"34",url:"",level:"2",children:[]},{caption:"Gunasekar, Arvind (20 October 2022).NDTV https://www.ndtv.com/india-news/ryan-school-murder-accused-gets-bail-after-5-years-of-detention-3448851",page:"34",url:"",level:"2",children:[]}]},{caption:"Kumar, Kunal (12 September 2017). \"Ryan murder: Blow-by-blow account of how Pradyuman Thakur was killed in his Gurgaon school\". India Today. https://www.indiatoday.in/india/story/ryan-international-school-gurgaon-murder-pradyuman-thakur-1042531-2017-09-11",page:"35",url:"",level:"1",children:[]},{caption:"\"Ryan school murder case: Boy who 'found body' could not write exam that day\". The Indian Express. 10 November 2017. https://indianexpress.com/article/india/ryan-school-murder-case-boy-who-found-body-could-not-write-exam-that-day-class-11-student-pradyuman-thakur-4930536/",page:"35",url:"",level:"1",children:[]},{caption:"\"Boy Was Carried By Alleged Killer After Being Found, Say Cops: 10 Points\". NDTV. 13 September 2017. https://www.firstpost.com/india/gurugram-school-murder-live-updates-acting-principal-of-ryan-international-school-suspended-4025281.html",page:"35",url:"",level:"1",children:[]},{caption:"\"Ryan student murder: Forensics team reaches school for clues, CBI initiates probe; top developments\". The Indian Express. 23 September 2017. Retrieved 3 September 2020. https://indianexpress.com/article/india/ryan-international-school-gurugram-cbi-probe-4857430/",page:"35",url:"",level:"1",children:[]},{caption:"\"Ryan school murder: CBI says Class 11 student 'killed' Pradyuman because he wanted exams postponed\". Hindustan Times. 8 November 2017. Retrieved 3 September 2020. https://www.hindustantimes.com/gurgaon/ryan-school-murder-class-11-student-allegedly-killed-pradyuman-to-have-exams-postponed-says-cbi/story-W018vMBUguvmArYXjbXf9H.html",page:"35",url:"",level:"1",children:[]},{caption:"\"CBI says 16-year-old Ryan student admits to killing Pradyumn\". Hindustan Times. 9 November 2017. Retrieved 3 September 2020. https://www.hindustantimes.com/gurgaon/cbi-says-16-year-old-ryan-student-admits-to-killing-pradyumn-takes-him-to-certain-place/story-q4K4VPZ1BWX2TpoOL1jdZN.html",page:"35",url:"",level:"1",children:[]},{caption:"THE GWALIOR BLIND MURDER MYSTERY.",page:"36",url:"",level:"1",children:[{caption:"the evidence and interrogated every shop selling omelets within a 200-meter radius. It was discovered that one vendor did see a woman with two men having omellete few hours back. But there was a lack of identification. The investigators made a sketch of the woman as the vendor explained. And then with the help of another new level technology clue that is – AI, the investigators digitally constructed the unidentified woman’s face and circulated the image, possibly aged 30-35yr across Gwalior using prominent channels.",page:"37",url:"",level:"2",children:[]},{caption:"On the other hand, missing person databases and the Crime and Criminal Tracking Network and Systems were scanned thoroughly. Later, it was narrowed down that the woman was named Sangeeta Pal and was a resident of Tikamgarh district who then resided separately in Gwalior. Even the vendor recognized selling her omelet and identified her with two other men. Following the vendor’s words, the police checked the nearby CCTV footage, which showed the woman walking with two men. Another major digital evidence was – online transactions made for the omelet by them. Based on this evidence, the police trailed down the city and found the prime accused – Sachin Sen, a 26-year-old man, resident of Gwalior. On Jan 5, 2026, he was arrested near Platform No. 4 of Gwalior railway station.",page:"37",url:"",level:"2",children:[]},{caption:"During interrogation, he confessed to murdering Sangeeta out of jealousy. It was then discovered that she had been living with him for the past 7-8 days. Sachin Sen also confessed that he was in a relationship with her and that he wanted to marry her, but he suspected that she was having multiple relationships with other men. On the day of the incident, he took the woman to the crime scene, made her drink alcohol, lured her into the bushes, raped her, and then killed her by hitting her face continuously with a stone so that she would not be identified.",page:"37",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"37",url:"",level:"1",children:[{caption:"Forensic experts used tailor marks and cell tower pings to identify the victim and suspect. DNA profiling then linked microscopic traces from the crime scene to the body. These digital and physical \"breadcrumbs\" successfully solved the nameless case.",page:"37",url:"",level:"2",children:[]}]},{caption:"Victim’s Background",page:"38",url:"",level:"1",children:[{caption:"After the Police teams reached Tikamgarh, where they gathered information about the victim. The investigation team also found that Sangeeta was a drug addict and had been multiple times before. She was separated from her last husband, named Pappu, two years ago. The name \"Pappu\" was found written on the hand of the victim, which was the second confirmation of the identity of the victim. People told the police that the victim was sometimes referred to as Kallo or Kalibai.",page:"38",url:"",level:"2",children:[]}]},{caption:"Judgement",page:"38",url:"",level:"1",children:[{caption:"As per the latest reliable information, the final judgment of the court in the Sangeeta Pal Murder Case has yet to be delivered. The case is in the trial stage after the arrest of the accused in the case. The main accused in the case, Sachin Sen, was arrested in January 2026 by the police",page:"38",url:"",level:"2",children:[]},{caption:"in Gwalior. According to the police, he confessed to the crime and was presented before the court. He has been remanded to judicial custody, and a chargesheet has been filed against him under Section 302 of the Indian Penal Code for the crime of murder.",page:"38",url:"",level:"2",children:[]}]},{caption:"References",page:"38",url:"",level:"1",children:[{caption:"Asian News International. (2026, January 6). How Gwalior cops cracked blind murder case using omelette clues, AI. NDTV. https://www.ndtv.com/india-news/how-gwalior-cops-cracked-blind-murder-case-using-omelette-clue-ai-10386054",page:"38",url:"",level:"2",children:[]},{caption:"The Times of India. (2026, January 6). Gwalior blind rape-murder case: How AI and omelette piece helped police nab culprit; victim remained nameless. https://timesofindia.indiatimes.com/city/bhopal/gwalior-blind-rape-murder-case-how-ai-and-omelette-piece-helped-police-nab-culprit-victim-remained-nameless/articleshow/126363716.cms",page:"38",url:"",level:"2",children:[]},{caption:"Bhaskar English. (2026). Gwalior murder case: AI reconstructs deceased woman’s identity; omelette piece on sweater key clue; lover arrested. https://www.bhaskarenglish.in/local/mp/news/gwalior-murder-case-ai-reconstructs-deceased-woman-identity-omelette-piece-on-sweater-key-clue-lover-arrested-136872573.html",page:"38",url:"",level:"2",children:[]}]},{caption:"THE ISLAND OF HORROR",page:"39",url:"",level:"1",children:[{caption:"Introduction",page:"39",url:"",level:"2",children:[]},{caption:"The Lolita",page:"39",url:"",level:"2",children:[]},{caption:"Nature Of Crime",page:"39",url:"",level:"2",children:[]},{caption:"Modus Operandi",page:"40",url:"",level:"2",children:[]},{caption:"Importance Of Digital Forensics",page:"40",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"40",url:"",level:"1",children:[]},{caption:"References",page:"41",url:"",level:"1",children:[]},{caption:"GLORIA RAMIREZ: THE TOXIC LADY",page:"42",url:"",level:"1",children:[{caption:"Introduction",page:"42",url:"",level:"2",children:[]},{caption:"Clinical Presentation And Time Course",page:"42",url:"",level:"2",children:[]},{caption:"Modus Operandi",page:"43",url:"",level:"2",children:[]},{caption:"The Autopsy And Toxicology Investigation",page:"43",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"43",url:"",level:"1",children:[]},{caption:"Aftermath And Medical Impact",page:"44",url:"",level:"1",children:[]},{caption:"Conclusion",page:"44",url:"",level:"1",children:[]},{caption:"References",page:"44",url:"",level:"1",children:[]},{caption:"Hektoen International. (2024, December 13). A case of toxic blood - Hektoen International. Hektoen International - An online medical humanities journal. https://hekint.org/2020/01/30/a-case-of-toxic-blood/",page:"45",url:"",level:"1",children:[]},{caption:"Medical mysteries. (n.d.). Forensic Science Center. https://forensicscience.llnl.gov/research/case-studies/mysteries",page:"45",url:"",level:"1",children:[]},{caption:"Senatra Silveira",page:"46",url:"",level:"1",children:[]},{caption:"FEATURE",page:"47",url:"",level:"1",children:[]},{caption:"ARTICLE",page:"47",url:"",level:"1",children:[]},{caption:"NEURO- FORENSICS",page:"48",url:"",level:"1",children:[{caption:"Edwin Kuruvilla",page:"48",url:"",level:"2",children:[]},{caption:"Introduction",page:"48",url:"",level:"2",children:[{caption:"“If every action is controlled by the brain, can a damaged brain be held guilty of a crime?”  “Should a person be held fully responsible for a crime if their brain is not functioning normally?",page:"48",url:"",level:"3",children:[]},{caption:"This question has given rise to neuroforensics, a field that dives deep into the relationship between brain activity, behaviour, and law. Neuroforensics is a forensic field that combines neuroscience and forensic science to study how brain function takes control of human behaviour and its relevance in criminal investigations.  Neuroforensics combines two different fields:",page:"48",url:"",level:"3",children:[]},{caption:"I. Neuroscience. Neuroscience studies how the brain works, including many different aspects like thinking, emotions and behaviour, control over actions.     II. Law and forensic science. The legal system focuses on:",page:"48",url:"",level:"3",children:[]},{caption:"Understanding guilt or innocence",page:"48",url:"",level:"3",children:[]},{caption:"Understanding a person's mental state",page:"48",url:"",level:"3",children:[]},{caption:"Focuses on answering questions like “Was",page:"48",url:"",level:"3",children:[{caption:"the person fully aware of their actions?” When talking about brain and behaviour. The brain is the main control center of the body, but human behaviour is not random but closely linked to the brain's functions. This tells us that every movement, thought, and reaction is a signal generated in the brain.",page:"49",url:"",level:"4",children:[]}]}]},{caption:"Brain And Behaviour",page:"49",url:"",level:"2",children:[{caption:"A major part of the brain which plays an important role is the frontal lobe. In simple words, the frontal lobe makes the person understand right and wrong and control. If this part is damaged, it leads to increased aggression and lack of self-control",page:"49",url:"",level:"3",children:[]},{caption:"Mood vs Personality",page:"49",url:"",level:"3",children:[{caption:"Mood is for a longer duration, so it is also referred to as an emotional state, whereas an effect is only for a shorter duration. Personality is the visible aspect of one’s character. e.g., how the person thinks, feels, behaves, etc., there are three things which decide our personality: the ego and the superego. EGO: Ego is based on the reality principle. The ego is responsible for dealing with reality. SUPEREGO: The superego guides us on what is right and wrong. The superego tries to make perfect behaviour.",page:"49",url:"",level:"4",children:[]}]}]},{caption:"Psychopath Personality",page:"49",url:"",level:"2",children:[{caption:"Psychopath personality is renamed as antisocial personality disorder. A psychopathic person can be categorized by:",page:"49",url:"",level:"3",children:[]},{caption:"ANTISOCIAL BEHAVIOR: either the person may be mentally ill or mentally defective. He may be a serial killer.",page:"49",url:"",level:"3",children:[]},{caption:"BOLDNESS: The person has no fear. The person can take a high risk capacity.",page:"49",url:"",level:"3",children:[]}]}]},{caption:"DID YOU KNOW",page:"49",url:"",level:"1",children:[{caption:"Lying is actually more \"cognitively expensive\" than telling the truth. When someone lies, the brain has to suppress the truth and then construct a narrative, which causes the Anterior Cingulate Cortex to light up under a scanner.",page:"49",url:"",level:"2",children:[]},{caption:"INTELLIGENCE: The person can plan and implement his acts perfectly and efficiently. He can understand what is right and wrong but he cannot stop himself from doing wrong.",page:"50",url:"",level:"2",children:[]},{caption:"EMOTIONS: the person feels no love, affection or sympathy for others. After committing a crime, he feels no empathy or love.",page:"50",url:"",level:"2",children:[]},{caption:"Example: TED BUNDY- he was an American serial killer, necrophiliac who kidnapped and murdered 30+ women. He used his perfect plan to abduct and kill women. He lacked emotion before and after committing the murders.",page:"50",url:"",level:"2",children:[]}]},{caption:"Importances",page:"50",url:"",level:"1",children:[{caption:"Neuroforensics play an important role in forensic science, which helps in criminal investigation by introducing the brain and",page:"50",url:"",level:"2",children:[]},{caption:"its functions as evidence to understand a person’s behaviour.",page:"50",url:"",level:"2",children:[]},{caption:"Mental state: It is very important to note down the person's mental state during the crime. This helps us to study",page:"50",url:"",level:"2",children:[]},{caption:"Whether the person was mentally aware of his actions",page:"50",url:"",level:"2",children:[]},{caption:"Able to understand what is right and wrong.",page:"50",url:"",level:"2",children:[]},{caption:"Brain injuries: injury to the frontal area( frontal lobe) leads to aggression/poor judgment. This type of injury affects behaviour and control over actions.",page:"50",url:"",level:"2",children:[]},{caption:"Neuroforensics has a significant role in forensic science by using the brain as a source of evidence. Brain injuries, particularly those affecting areas responsible for judgment and control, can influence a person’s behaviour and decision-making. In addition, the mental state of an individual at the time of the crime is carefully evaluated to determine whether they were aware of their actions and capable of understanding right and wrong.",page:"50",url:"",level:"2",children:[]}]},{caption:"Case Study",page:"50",url:"",level:"1",children:[{caption:"SELVI VS STATE OF KARNATAKA The case of Selvi vs State of Karnataka (2010) is a landmark judgment by the Supreme Court of India, which significantly impacted the legal landscape regarding the admissibility of certain types of evidence in court.",page:"50",url:"",level:"2",children:[]}]},{caption:"Different Techniques",page:"51",url:"",level:"1",children:[]},{caption:"Conclusion",page:"51",url:"",level:"1",children:[]},{caption:"References",page:"51",url:"",level:"1",children:[]},{caption:"HOW DO CRIMINAL MINDS GET AFFECTED BY MOVIES AND MEDIA?",page:"52",url:"",level:"1",children:[{caption:"Case Studies: Real-Life Crimes Inspired by Films",page:"53",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"53",url:"",level:"1",children:[]},{caption:"Dealing With The Media's Influence On Crime Impressions",page:"54",url:"",level:"1",children:[]},{caption:"Conclusion",page:"54",url:"",level:"1",children:[]},{caption:"References",page:"54",url:"",level:"1",children:[]},{caption:"Media-Inspired Crimes (News Articles & Reports)",page:"55",url:"",level:"1",children:[]},{caption:"The Times of India. (2022, January 5). Inspired by 'Pushpa', Delhi teens turn to crime. https://timesofindia.indiatimes.com/",page:"55",url:"",level:"1",children:[]},{caption:"The Hindu. (2022, September 10). Youth inspired by KGF2 turns serial killer. https://www.thehindu.com/",page:"55",url:"",level:"1",children:[]},{caption:"India Today. (2019, October 11). Johny Dada killed Delhi air hostess inspired by Kabir https://www.indiatoday.in /",page:"55",url:"",level:"1",children:[]},{caption:"The Indian Express. (2015, May 14). Drishyam inspires man to kill and hide body. https://indianexpress.com/",page:"55",url:"",level:"1",children:[]},{caption:"Hindustan Times. (2021, August 28). Inspired by ‘Money Heist’, gang robs jewelry shop in Lucknow https://www.hindustantimes.com/",page:"55",url:"",level:"1",children:[]},{caption:"Media and Justice Reform Examples",page:"55",url:"",level:"1",children:[]},{caption:"DuVernay, A. (Director). (2016). 13th [Film]. Netflix.",page:"55",url:"",level:"1",children:[]},{caption:"DuVernay, A. (Creator). (2019). When They See Us [TV series]. Netflix.",page:"55",url:"",level:"1",children:[]},{caption:"TRACING CRIME THROUGH BLOODLINES: THE RISE OF FORENSIC GENEALOGY",page:"56",url:"",level:"1",children:[{caption:"Methodology",page:"57",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"57",url:"",level:"1",children:[]},{caption:"Case Study",page:"58",url:"",level:"1",children:[]},{caption:"Advantages",page:"58",url:"",level:"1",children:[]},{caption:"Ethical Concerns",page:"59",url:"",level:"1",children:[]},{caption:"Conclusion",page:"59",url:"",level:"1",children:[]},{caption:"References",page:"59",url:"",level:"1",children:[]},{caption:"Hester, S. (2023). An assessment of the forensic aspects of genetic genealogy (Master’s thesis, West Virginia University). https://researchrepository.wvu.edu/cgi/viewcontent.cgi?params=/context/etd/article/12626/&path_info=Hester_Thesis_Final_w_Revisions.pdf",page:"60",url:"",level:"1",children:[]},{caption:"Katsanis, S. H. (2020). Pedigrees and perpetrators: Uses of DNA and genealogy in forensic investigations. Annual Review of Genomics and Human Genetics, 21(1), 535–564. https://www.annualreviews.org/content/journals/10.1146/annurev-genom-111819-084213",page:"60",url:"",level:"1",children:[]},{caption:"APPLICATION OF FORENSIC ANTHROPOLOGY IN BURNED AND DECOMPOSED BODIES",page:"61",url:"",level:"1",children:[{caption:"700–800°C. These color changes are predictable. Microscopic surface striations are produced by low-grade heating (<275°C), but bone becomes more porous and brittle above ~275°C. The bone mineral itself starts to calcine and shrink at about 600–800°C, producing white, powdery, brittle pieces. These changes break down organic parts. First, collagen and bone proteins break down, and then the mineral crystallinity changes. As the color changes, DNA is slowly lost. Teeth have a lot of minerals that protect DNA, so posterior teeth often have DNA that can be recovered even when bones do not. On the other hand, bone that has been completely calcined has almost no amplifiable DNA.",page:"62",url:"",level:"2",children:[]},{caption:"Thermal fractures can also happen when things get heated. Under heat stress, bone can crack and warp, creating heat fractures with curved or polygonal patterns. These can look like trauma that happened just before death. To tell the difference between heat-induced breaks and real injuries, you need to look closely at the fracture surfaces and the situation.",page:"62",url:"",level:"2",children:[]},{caption:"Decomposition Stages and Environmental Factors",page:"62",url:"",level:"2",children:[{caption:"After death, a body passes through recognized decomposition stages:",page:"62",url:"",level:"3",children:[]},{caption:"Fresh (Autolysis): Immediately postmortem; cells self-digest, rigor mortis sets in.",page:"62",url:"",level:"3",children:[]},{caption:"Bloat: Bacteria produce gases, body swells, odor develops.",page:"62",url:"",level:"3",children:[]},{caption:"Active Decay: Soft tissues liquefy, rapid mass loss, intense insect activity.",page:"62",url:"",level:"3",children:[]},{caption:"Advanced Decay: Most soft tissue is gone, decay slows.",page:"62",url:"",level:"3",children:[]},{caption:"Dry/Skeletonization: Only bones and some dried tissue remain.",page:"62",url:"",level:"3",children:[]},{caption:"These stages occur in order, but timing varies enormously with conditions. Warm, humid climates or hot seasons speed up decomposition via higher bacterial and insect activity. In contrast, cold or dry conditions slow decay significantly. Environmental modifiers include:",page:"62",url:"",level:"3",children:[]},{caption:"Temperature: Each +10°C roughly doubles decay rate.",page:"62",url:"",level:"3",children:[]},{caption:"Insects and Scavengers: Flies and beetles accelerate tissue breakdown.",page:"62",url:"",level:"3",children:[]},{caption:"Moisture: Water or burial can slow oxygen-dependent processes.",page:"62",url:"",level:"3",children:[]},{caption:"Depth and Location: Buried bodies decompose slower than exposed ones.",page:"62",url:"",level:"3",children:[]},{caption:"Clothing/Coverings: Can retain heat or block scavengers.",page:"62",url:"",level:"3",children:[]}]}]},{caption:"DID YOU KNOW",page:"62",url:"",level:"1",children:[]},{caption:"Identification Challenges",page:"63",url:"",level:"1",children:[]},{caption:"Conclusion",page:"63",url:"",level:"1",children:[]},{caption:"References",page:"64",url:"",level:"1",children:[]},{caption:"Malavika Gopurathingal",page:"65",url:"",level:"1",children:[]},{caption:"REVIEW",page:"66",url:"",level:"1",children:[]},{caption:"LITERATURE",page:"66",url:"",level:"1",children:[]},{caption:"CLOUD FORENSICS: CHALLENGES IN EVIDENCE ACQUISITION AND INTEGRITY PRESERVATION",page:"67",url:"",level:"1",children:[{caption:"Introduction",page:"67",url:"",level:"2",children:[]},{caption:"Overview Of Cloud Forensic",page:"68",url:"",level:"2",children:[]},{caption:"Data Acquisition In Cloud Environments",page:"68",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"68",url:"",level:"1",children:[]},{caption:"Challenges In Data Acquisition",page:"69",url:"",level:"1",children:[]},{caption:"Data Preservation In Cloud Forensic",page:"69",url:"",level:"1",children:[]},{caption:"Challenges In Data Preservation",page:"70",url:"",level:"1",children:[]},{caption:"Tools And Techniques In Cloud Forensic",page:"70",url:"",level:"1",children:[]},{caption:"Legal And Ethical Considerations",page:"71",url:"",level:"1",children:[]},{caption:"Case Study",page:"71",url:"",level:"1",children:[]},{caption:"Conclusion",page:"72",url:"",level:"1",children:[]},{caption:"References",page:"72",url:"",level:"1",children:[]},{caption:"Le-Khac, N.-A., Mollema, M., Craig, R., Ryder, S., & Chen, L. (Year). Data acquisition in the cloud. In L. Chen, H. Takabi, & N.-A. Le-Khac (Eds.), Security, privacy, and digital forensics in the cloud. Wiley. https://ieeexplore.ieee.org/document/9821318",page:"73",url:"",level:"1",children:[]},{caption:"Purnaye, P., & Jyotinagar, V. (2015). Cloud forensics: Volatile data preservation. International Journal of Computer Science and Engineering (IJCSE). https://www.ijcse.net/docs/IJCSE15-04-02-040.pdf",page:"73",url:"",level:"1",children:[]},{caption:"SentinelOne. (n.d.). What is cloud forensics? https://www.sentinelone.com/cybersecurity-101/cloud-security/what-is-cloud-forensics",page:"73",url:"",level:"1",children:[]},{caption:"YouAccel. (n.d.). Legal considerations in cloud forensics. https://youaccel.com/lesson/legal-considerations-in-cloud-forensics/premium",page:"73",url:"",level:"1",children:[]},{caption:"Computer Emergency Response Team for the EU (CERT-EU). (2019). Massive breach at Capital One, purportedly due to a cloud misconfiguration (Threat Memo 190802-1). https://cert.europa.eu/publications/threat-intelligence/threat-memo-190802-1/pdf",page:"73",url:"",level:"1",children:[]},{caption:"INDUCTIVELY COUPLED PLASMA: A POWERFUL TOOL",page:"74",url:"",level:"1",children:[{caption:"Introduction",page:"74",url:"",level:"2",children:[]},{caption:"Background And Inventions",page:"74",url:"",level:"2",children:[]},{caption:"Working Mechanism",page:"74",url:"",level:"2",children:[{caption:"The ions produced are directed to the mass spectrometer and separated according to their m/z ratio. The ion count is made by the instrument, and the quantity of each element in the sample is recorded.",page:"75",url:"",level:"3",children:[]},{caption:"A solid sample requires LA-ICP-MS, where the sample has been vaporized with a laser to produce a small volume of vapour for the analysis of trace elements.",page:"75",url:"",level:"3",children:[]}]},{caption:"Applications In Forensic Science",page:"75",url:"",level:"2",children:[{caption:"Due to its ultra-sensitive property and multi-elemental analysis of trace evidence, it plays a significant role in the field of forensic science. Its key applications include:",page:"75",url:"",level:"3",children:[]},{caption:"Gunshot Residue (GSR): When a culprit fires a gun, then some amount of trace elements like lead and barium can stick on their hand or clothes. ICP-MS can detect these particles and determine whether someone has fired a gun.",page:"75",url:"",level:"3",children:[]},{caption:"Glass fragments: When a glass is broken in a case like burglary, then tiny pieces of glass might stick to the suspect’s clothes. ICP-MS helps to match those broken pieces of glass to the source.",page:"75",url:"",level:"3",children:[]},{caption:"Paint and Metal Chips: In hit-and-run cases, the paint chip of the car could be matched from the suspect’s vehicle with the help of ICP-MS.",page:"75",url:"",level:"3",children:[]},{caption:"Soil and ink: Soil could be matched from the suspect’s shoes to the crime scene, and ink could be used to trace a specific pen or printer.",page:"75",url:"",level:"3",children:[]},{caption:"Biological tissues- ICP-MS can detect toxic metals in bone, hair, or other organs, which play a crucial role in poisoning cases and environmental exposure cases.",page:"75",url:"",level:"3",children:[]}]}]},{caption:"DID YOU KNOW",page:"75",url:"",level:"1",children:[{caption:"An ICP torch is hotter than the surface of the Sun, reaching temperatures up to 10,000 K to instantly break down any chemical bond.",page:"75",url:"",level:"2",children:[]}]},{caption:"Real Life Examples",page:"76",url:"",level:"1",children:[]},{caption:"Advantages",page:"76",url:"",level:"1",children:[]},{caption:"Disadvantages",page:"76",url:"",level:"1",children:[]},{caption:"Legal And Admissibility Aspects",page:"76",url:"",level:"1",children:[]},{caption:"Conclusion",page:"76",url:"",level:"1",children:[]},{caption:"References",page:"77",url:"",level:"1",children:[]},{caption:"DEEPFAKES AND DIGITAL FORENSICS",page:"78",url:"",level:"1",children:[{caption:"Abstract",page:"78",url:"",level:"2",children:[]},{caption:"Introduction",page:"78",url:"",level:"2",children:[]},{caption:"Deepfake Technology And Generation Methods",page:"79",url:"",level:"2",children:[]},{caption:"Deepfakes And Digital Forensics",page:"79",url:"",level:"2",children:[]}]},{caption:"DID YOU KNOW",page:"79",url:"",level:"1",children:[{caption:"content. Deepfake forensics can be referred to as a subdiscipline of digital forensics concerned with the detection of synthetic media.",page:"80",url:"",level:"2",children:[]}]},{caption:"Deepfake Detection Techniques",page:"80",url:"",level:"1",children:[{caption:"Deepfake detection technologies can generally be classified into forensic-based technologies and deep learning-based detection technologies. Forensic-based technologies are based on finding visual and auditory discrepancies, such as lighting discrepancies, shadow inconsistency, unusual blinking behaviour, unnatural head movements, and compression artifacts. They are based on the premise that deepfake generation systems usually generate images that contain visual inconsistencies, which are used by deepfake detection tools. Recently, some deep learning-based detection technologies that include CNNs, RNNs, and transformers have been developed for detecting deepfakes. These technologies involve training of CNNs, RNNs, and transformers on a database comprising real images and fake images to learn patterns in data that separate fake from real. Deep learning-based technologies have a high accuracy level as compared to traditional detection technologies, but these methods also have some limitations, including overfitting and reliance on data.",page:"80",url:"",level:"2",children:[]},{caption:"Biological signal analysis is yet another emerging technology in detecting deepfake videos. Biological signals analysis involves the analysis of biological signals like heart rate, eye blinking rate, facial microexpressions, etc. Deepfake videos may not properly reproduce these signals, thus making them an ideal candidate for detecting deepfakes.",page:"80",url:"",level:"2",children:[]},{caption:"Detection Method",page:"80",url:"",level:"2",children:[]},{caption:"Usage in Research (%)",page:"80",url:"",level:"2",children:[]},{caption:"CNN",page:"80",url:"",level:"2",children:[{caption:"38%",page:"80",url:"",level:"3",children:[]}]},{caption:"RNN",page:"80",url:"",level:"2",children:[{caption:"14%",page:"80",url:"",level:"3",children:[]},{caption:"Transformer",page:"80",url:"",level:"3",children:[]},{caption:"18%",page:"80",url:"",level:"3",children:[]},{caption:"Image Forensic Techniques",page:"80",url:"",level:"3",children:[]},{caption:"16%",page:"80",url:"",level:"3",children:[]},{caption:"Biological Signal Analysis",page:"80",url:"",level:"3",children:[]},{caption:"14%",page:"80",url:"",level:"3",children:[]},{caption:"CNN-based deep learning models are the most commonly used methods for deepfake detection, followed by transformer-based models and traditional image forensic techniques.",page:"80",url:"",level:"3",children:[]}]}]},{caption:"Challenges In Deepfake Digital Forensics",page:"81",url:"",level:"1",children:[]},{caption:"Applications of Deepfake Forensics",page:"81",url:"",level:"1",children:[]},{caption:"Future Research Directions",page:"81",url:"",level:"1",children:[]},{caption:"Conclusion",page:"82",url:"",level:"1",children:[]},{caption:"References",page:"82",url:"",level:"1",children:[]},{caption:"Rubén, T. M., Rubén, V. R., Julián, F. A., Aythami, M. M., & Javier, O. G. (2020). Deepfakes and beyond: A Survey of face manipulation and fake detection. Biblos-e Archivo (Universidad Autónoma De Madrid). https://doi.org/10.1016/j.inffus.2020.06.014",page:"83",url:"",level:"1",children:[]},{caption:"Verdoliva, L. (2020). Media Forensics and DeepFakes: An Overview. IEEE Journal of Selected Topics in Signal Processing, 14(5), 910–932. https://doi.org/10.1109/jstsp.2020.3002101",page:"83",url:"",level:"1",children:[]},{caption:"Rana, M. S., Nobi, M. N., Murali, B., & Sung, A. H. (n.d.). Deepfake Detection: A Systematic Literature Review. The Aquila Digital Community. https://aquila.usm.edu/fac_pubs/19969/",page:"83",url:"",level:"1",children:[]},{caption:"Passos, L. A., Jodas, D., Costa, K. a. P., Júnior, L. a. S., Rodrigues, D., Del Ser, J., Camacho, D., & Papa, J. P. (2024). A review of deep learning‐based approaches for deepfake content detection. Expert Systems, 41(8). https://doi.org/10.1111/exsy.13570",page:"83",url:"",level:"1",children:[]},{caption:"Vamsi, V. V. V. N. S., Shet, S. S., Reddy, S. S. M., Rose, S. S., Shetty, S. R., Sathvika, S., S, S. M., & Shankar, S. P. (2022). Deepfake detection in digital media forensics. Global Transitions Proceedings, 3(1), 74–79. https://doi.org/10.1016/j.gltp.2022.04.017",page:"83",url:"",level:"1",children:[]},{caption:"Bendiab, G., Haiouni, H., Moulas, I., & Shiaeles, S. (2024). Deepfakes in digital media forensics: Generation, AI-based detection and challenges. Journal of Information Security and Applications, 88, 103935. https://doi.org/10.1016/j.jisa.2024.103935",page:"83",url:"",level:"1",children:[]},{caption:"Alshammari, H., & Elleithy, K. (2023). Deep Fake and Digital Forensics. In 2023 IEEE 14th Annual Ubiquitous Computing, Electronics & Mobile Communication Conference (UEMCON) (pp. 0283–0288). https://doi.org/10.1109/uemcon59035.2023.10315974",page:"83",url:"",level:"1",children:[]},{caption:"CONTRIBUTORS",page:"85",url:"",level:"1",children:[{caption:"NAME",page:"85",url:"",level:"2",children:[]}]},{caption:"https://forms.gle/BDDdWZuPewcF1ZYM9",page:"86",url:"",level:"1",children:[]}];